//! ATDD red-phase scaffolds for story 1 — container transport skeleton.
//!
//! Generated by the `bmad-testarch-atdd` workflow (see
//! `_bmad-output/test-artifacts/atdd-checklist-1-container-transport-skeleton.md`).
//! Rust has no `test.skip()`: `#[ignore = "ATDD RED: …"]` is the red-phase
//! marker. Each leaf carries exactly one criterion id in its doc comment and
//! ignore reason because a Rust identifier cannot contain a `-`.
//!
//! This module lives beside the implementation rather than in `tests/` because
//! AC-2 and AC-3 pin crate-private seams (`remember`/`Proved` and `relocation`)
//! that the public API deliberately does not expose. It adds no production code.

use super::*;
use crate::core::session::RemoteTarget;
use crate::daemon::remote_link::LinkKind;
use crate::daemon::router::RouteHeader;

/// A realistic installed path; the value only has to be a path the memo can
/// hand back verbatim.
const SERVER: &str = "/home/dev/.local/share/tty7/bin/tty7-server-linux-musl";

#[test]
#[ignore = "ATDD RED: activate when implementing AC-1 (registering a running container opens a shell inside it)"]
fn ac1_registering_a_running_container_opens_a_shell_inside_it() {
    // AC-1: the pane process is `docker exec -i web <server> --stdio --pane` —
    // the daemon and its shell run *inside* the container, on the host's docker
    // channel. This is the promise a live container would prove end to end.
    let pane = docker_args("web", &[SERVER, "--stdio", "--pane"]);
    assert_eq!(
        pane,
        ["exec", "-i", "web", SERVER, "--stdio", "--pane"],
        "a container pane must run its server inside `web` over the host's docker exec channel"
    );

    // Secondary: the workspace is tagged as a container, not as local or SSH.
    // The tag is the other half of AC-1, asserted after the transport because
    // the transport is what makes the shell exist at all.
    let header = RouteHeader::container("web").for_pane();
    assert_eq!(header.describe(), "container web");
    assert_eq!(header.target.origin_key(), "container:web");

    let target = RemoteTarget::Container {
        container: "web".into(),
    };
    assert_eq!(target.connection_key(), "container:web");
    assert!(
        target.hosts_our_server(),
        "a container owns an install and can be restarted"
    );
    assert!(
        !target.is_ssh(),
        "a container is reached over docker exec, not an SSH connection"
    );
    assert_eq!(LinkKind::Container.label(), "container-stdio");
}

#[test]
#[ignore = "ATDD RED: activate when implementing AC-2 (reopening the same container reuses the server)"]
fn ac2_reopening_the_same_container_reuses_the_proved_server() {
    // AC-2: the second open answers from the memo before any docker probe. A
    // re-push (or a re-probe) would leave the memo short-circuit and fail on
    // this host, where no docker CLI exists.
    let container = format!("atdd-reopen-{}", std::process::id());
    forget_container_server(&container);
    remember(
        &container,
        Proved {
            binary: SERVER.to_string(),
            mismatch: None,
        },
    );

    let reused = ensure_container_server(&container);

    assert_eq!(
        reused.as_deref().ok(),
        Some(SERVER),
        "the second open must reuse the proved server, not re-push or re-probe it"
    );

    forget_container_server(&container);
}

#[test]
#[ignore = "ATDD RED: activate when implementing AC-3 (noexec home relocates or states why not)"]
fn ac3_a_noexec_home_relocates_the_server_or_states_why_it_cannot() {
    // AC-3, relocation arm: the probe skipped `$HOME` because its bin directory
    // cannot hold an executable, and accepted a runtime base instead.
    assert_eq!(
        relocation("/home/dev", Some("/run/user/1000".to_string())),
        Ok(Some("/run/user/1000".to_string())),
        "the server must relocate to the executable writable base instead of $HOME"
    );

    // AC-3, degradation arm: no candidate is executable, so the failure has to
    // name the home and the reason rather than installing somewhere that cannot
    // run the binary.
    let degraded = relocation("/home/dev", None)
        .expect_err("nowhere executable must degrade, not pretend to install");
    assert!(
        degraded.contains("/home/dev"),
        "the degraded reason must name the home: {degraded:?}"
    );
    assert!(
        degraded.contains("unwritable or mounted noexec"),
        "the degraded reason must state why: {degraded:?}"
    );
}

#[test]
#[ignore = "ATDD RED: activate when implementing AC-4 (a --network none container pane still works)"]
fn ac4_a_network_none_container_pane_uses_the_host_docker_channel() {
    // AC-4: transport is `docker exec` over the host's docker socket. No tty,
    // no network attachment, no in-container listener — so a `--network none`
    // container behaves exactly like any other.
    let argv = docker_args("air-gapped", &[SERVER, "--stdio"]);
    assert_eq!(
        argv,
        ["exec", "-i", "air-gapped", SERVER, "--stdio"],
        "the pane protocol must ride `docker exec` over the host socket"
    );

    assert!(
        !argv
            .iter()
            .any(|a| a == "-t" || a.starts_with("--network") || a == "run"),
        "no tty allocation and no network attachment belong on the container link"
    );
    assert_eq!(host_label("air-gapped"), "container:air-gapped");
}
